796	        const snapshot = {
797	          v: 1,
798	          gen,
799	          seq,
800	          bytes,
801	          published,
802	          replayed,
803	          horizon,
804	          positions: Object.fromEntries(positions),
805	          dedup: Array.from(dedup.entries()),
806	          messages,
807	        };
