import {
  openSync,
  closeSync,
  writeSync,
  fsyncSync,
  mkdirSync,
  readFileSync,
  writeFileSync,
  truncateSync,
  renameSync,
  rmSync,
  existsSync,
  readdirSync,
  statSync,
} from 'node:fs';
import path from 'node:path';
import { randomUUID } from 'node:crypto';

const LOG_NAME = 'bus.jsonl';
const LOG_TMP_NAME = 'bus.log.tmp';
const SNAPSHOT_NAME = 'bus.snapshot.json';
const SNAPSHOT_TMP_NAME = 'bus.snapshot.tmp';
const LEASE_NAME = 'bus.lock.json';
const LEASE_TMP_NAME = 'bus.lock.tmp';
// The log is a chain of segment files: the active `bus.jsonl` plus finalized
// `bus.<index>.jsonl` segments. Index order is oldest first; an index is
// never reused within the lifetime of a directory.
const SEGMENT_RE = /^bus\.(\d+)\.jsonl$/;
const segmentName = (index) => `bus.${String(index).padStart(10, '0')}.jsonl`;

// Cross-process write ownership rides on a single lease file. A writer holds
// the lease for LEASE_MS and keeps renewing it while work is queued; when it
// goes idle or closes it releases the lease early so a contender does not
// have to wait for a timeout.
const LEASE_MS = 4000;
// Renew with this much headroom so ordinary scheduler/IO latency cannot make
// a healthy owner look expired.
const RENEW_AT_MS = 2000;
// Conservative bound on how far two wall clocks may disagree. A lease is
// treated as expired only past its deadline plus this grace, so clock skew
// can never make an (in its own frame still-valid) owner's token pass here.
const CLOCK_SKEW_MS = 1000;
// A contender retries acquisition at this cadence while another owner's
// lease is still valid; ENOSPC/EACCES on the lease file surface immediately.
const RETRY_MS = 50;

/**
 * Validate that `value` survives a compact JSON.stringify unchanged.
 * JSON silently drops undefined / functions and turns non-finite numbers
 * into null; the spec rejects those along with BigInt and circular
 * references as TypeError.
 */
function assertJsonSafe(value, stack = new Set()) {
  if (typeof value === 'bigint') {
    throw new TypeError('record contains a BigInt');
  }
  if (typeof value === 'function') {
    throw new TypeError('record contains a function');
  }
  if (typeof value === 'undefined') {
    throw new TypeError('record contains undefined');
  }
  if (typeof value === 'number' && !Number.isFinite(value)) {
    throw new TypeError('record contains a non-finite number');
  }
  if (value !== null && typeof value === 'object') {
    // Unbox boxed primitives (e.g. new Number(NaN)) before recursing.
    if (value instanceof Number || value instanceof String || value instanceof Boolean) {
      assertJsonSafe(value.valueOf(), stack);
      return;
    }
    if (stack.has(value)) {
      throw new TypeError('record contains a circular reference');
    }
    stack.add(value);
    if (Array.isArray(value)) {
      for (const item of value) assertJsonSafe(item, stack);
    } else {
      for (const key of Object.keys(value)) assertJsonSafe(value[key], stack);
    }
    stack.delete(value);
  }
}

/**
 * Split a jsonl buffer into parsed entries. `durable` is the offset just
 * past the final newline; anything beyond it is a torn trailing write.
 */
function parseLog(raw) {
  const entries = [];
  let start = 0;
  for (let i = 0; i < raw.length; i++) {
    if (raw[i] === 0x0a) {
      if (i > start) entries.push(JSON.parse(raw.toString('utf8', start, i)));
      start = i + 1;
    }
  }
  return { entries, durable: start };
}

// Parse every complete, committed line of a log buffer. Recovery is strict
// (a torn final line is a fatal surprise and severs the tail); reads are
// lenient — a torn tail or a batch whose commit has not landed yet is simply
// not visible.
function parseCommitted(raw, { strict = false } = {}) {
  const entries = [];
  let start = 0;
  let group = null;
  for (let i = 0; i < raw.length; i++) {
    if (raw[i] !== 0x0a) continue;
    let entry = null;
    try {
      entry = i > start ? JSON.parse(raw.toString('utf8', start, i)) : null;
    } catch (err) {
      if (strict) throw err;
      return entries;
    }
    if (group !== null) {
      if (entry && entry.t === 'bk' && entry.id === group.id) {
        entries.push(...group.entries);
        group = null;
      } else if (entry && entry.t === 'b') {
        // The previous group never committed; track the new one instead.
        group = { id: entry.id, entries: [] };
      } else if (entry) {
        group.entries.push(entry);
      }
    } else if (entry && entry.t === 'b') {
      group = { id: entry.id, entries: [] };
    } else if (entry) {
      entries.push(entry);
    }
    start = i + 1;
  }
  return entries;
}

export function createBus({ path: dir, fsync = false, maxBytes } = {}) {
  if (typeof dir !== 'string' || dir.length === 0) {
    throw new TypeError('createBus: "path" must be a non-empty string');
  }
  // Omitted (undefined) means unlimited; any given value must be a positive
  // integer — zero, negatives, fractions and non-numbers are TypeErrors.
  let quota;
  if (maxBytes !== undefined) {
    if (typeof maxBytes !== 'number' || !Number.isInteger(maxBytes) || maxBytes <= 0) {
      throw new TypeError('createBus: "maxBytes" must be a positive integer');
    }
    quota = maxBytes;
  }

  const logPath = path.join(dir, LOG_NAME);
  const logTmpPath = path.join(dir, LOG_TMP_NAME);
  const snapshotPath = path.join(dir, SNAPSHOT_NAME);
  const snapshotTmpPath = path.join(dir, SNAPSHOT_TMP_NAME);
  const leasePath = path.join(dir, LEASE_NAME);
  const leaseTmpPath = path.join(dir, LEASE_TMP_NAME);

  let seq = 0; // seq of the last effective message
  let bytes = 0;
  let published = 0;
  let replayed = 0;
  // dedupKey -> { id, seq } for effective messages
  const dedup = new Map();
  // dedupKey -> { promise, resolve, reject } for first publish in flight
  const pending = new Map();
  // dedupKey -> { promise, resolve, reject } reserved by the first
  // in-flight batch carrying that key; lets later singles/batches share
  // the batch's first acknowledgement just like `pending` does for singles
  const groupPending = new Map();
  // consumer name -> position (seq of the last consumed message; 0 = none)
  const positions = new Map();
  // generation of the newest durable snapshot; 0 = no snapshot yet
  let snapshotGen = 0;
  // messages folded into the snapshot, served to replay/read after truncation
  let baseMessages = [];
  // Every message with seq <= horizon has been discarded by truncate().
  let horizon = 0;
  // Every message with seq <= foldedSeq lives in the snapshot, not the log.
  let foldedSeq = 0;
  // Index handed to the next finalized segment; never reused within a run.
  let nextSegmentIndex = 1;
  // Business bytes of the messages still retained (seq > horizon, i.e.
  // snapshot survivors plus live-log messages). Unlike the cumulative
  // `bytes` stat this shrinks when retention truncation frees messages;
  // compaction only reshapes the log and never changes it.
  let usageBytes = 0;

  // ---- cross-process lease state -------------------------------------------
  // Ownership is taken lazily, only when a write-path call first needs it, so
  // a read-only opener never contends. `ownerId` is this process's identity
  // for as long as the instance lives; `epoch` is bumped on every takeover so
  // a stale owner recognises its old token even when wall clocks disagree.
  const ownerId = randomUUID();
  let leaseEpoch = 0;
  let leaseExpiresAt = 0;
  let heartbeat = null;
  let leaseBusy = 0;

  // ---- synchronous recovery so stats() is correct the moment createBus returns
  mkdirSync(dir, { recursive: true });

  // A leftover tmp file is a snapshot that crashed mid-write. The pre-compact
  // log is still intact, so the half snapshot carries no state: drop it.
  rmSync(snapshotTmpPath, { force: true });
  // Likewise a log tmp left behind when compact crashed before the rename:
  // the live log (if any) is still the source of truth.
  rmSync(logTmpPath, { force: true });
  // A lease tmp is an abandoned atomic-rename attempt; the lease it aimed at
  // is whatever currently sits under the final name.
  rmSync(leaseTmpPath, { force: true });

  if (existsSync(snapshotPath)) {
    const snap = JSON.parse(readFileSync(snapshotPath, 'utf8'));
    snapshotGen = snap.gen;
    seq = snap.seq;
    bytes = snap.bytes;
    published = snap.published;
    replayed = snap.replayed;
    // Snapshots written before truncation existed carry no horizon.
    horizon = snap.horizon ?? 0;
    foldedSeq = snap.seq;
    for (const [key, value] of snap.dedup) dedup.set(key, value);
    for (const [name, pos] of Object.entries(snap.positions)) positions.set(name, pos);
    baseMessages = snap.messages;
  }

  const applyEntry = (entry) => {
    if (entry.t === 'm') {
      // At/below the horizon the message was discarded by truncation; only
      // its cumulative counters (carried by the marker) survive.
      if (entry.seq <= horizon) return;
      seq = entry.seq;
      bytes += entry.bytes;
      published += 1;
      if (typeof entry.d === 'string') {
        dedup.set(entry.d, { id: entry.id, seq: entry.seq });
      }
    } else if (entry.t === 's') {
      replayed += entry.n;
    } else if (entry.t === 'p') {
      positions.set(entry.name, entry.pos);
    }
  };

  // A truncate marker is an absolute checkpoint: the cumulative counters,
  // positions and dedup table it carries replace whatever earlier segments
  // established, so recovery can start from the newest marker and ignore
  // everything before it.
  const applyMarker = (entry) => {
    seq = entry.seq;
    bytes = entry.bytes;
    published = entry.published;
    replayed = entry.replayed;
    horizon = entry.horizon;
    positions.clear();
    for (const [name, pos] of Object.entries(entry.positions)) positions.set(name, pos);
    dedup.clear();
    for (const [key, value] of entry.dedup) dedup.set(key, value);
  };

  const markerLine = (gen) => JSON.stringify({ t: 'c', gen }) + '\n';

  // Replay complete log lines and apply only the committed prefix.
  // A batch is bracketed by {t:'b',id} .. entries .. {t:'bk',id}: a begin
  // without its matching commit (crash mid-write, or overtaken by a newer
  // begin) is severed wholesale and none of its entries take effect.
  // Returns the byte offset just past the last committed line, so both a
  // torn trailing write and an uncommitted batch tail can be truncated.
  const recoverLog = (raw) => {
    let lineStart = 0;
    let committedEnd = 0;
    let group = null;
    for (let i = 0; i < raw.length; i++) {
      if (raw[i] !== 0x0a) continue;
      const entry = i > lineStart ? JSON.parse(raw.toString('utf8', lineStart, i)) : null;
      if (group !== null) {
        if (entry && entry.t === 'bk' && entry.id === group.id) {
          for (const e of group.entries) applyEntry(e);
          group = null;
          committedEnd = i + 1;
        } else if (entry && entry.t === 'b') {
          // The previous group never committed; start tracking the new one.
          group = { id: entry.id, entries: [] };
        } else if (entry) {
          group.entries.push(entry);
        }
      } else if (entry && entry.t === 'b') {
        group = { id: entry.id, entries: [] };
      } else {
        if (entry) {
          if (entry.t === 't') applyMarker(entry);
          else applyEntry(entry);
        }
        committedEnd = i + 1;
      }
      lineStart = i + 1;
    }
    return committedEnd;
  };

  // Finalized segments present in the directory, oldest first.
  const listSegments = () => {
    const out = [];
    for (const name of readdirSync(dir)) {
      const match = SEGMENT_RE.exec(name);
      if (match) out.push({ index: Number(match[1]), path: path.join(dir, name) });
    }
    out.sort((a, b) => a.index - b.index);
    return out;
  };

  // First complete line of a log file, or null when there is none.
  const firstEntry = (filePath) => {
    const raw = readFileSync(filePath);
    const nl = raw.indexOf(0x0a);
    if (nl <= 0) return null;
    try {
      return JSON.parse(raw.toString('utf8', 0, nl));
    } catch {
      return null;
    }
  };

  // Highest message seq in a segment file; null when it carries no messages.
  const segmentMaxSeq = (filePath) => {
    const { entries } = parseLog(readFileSync(filePath));
    let max = null;
    for (const entry of entries) {
      if (entry.t === 'm' && (max === null || entry.seq > max)) max = entry.seq;
    }
    return max;
  };

  const segments = listSegments();
  for (const seg of segments) {
    if (seg.index >= nextSegmentIndex) nextSegmentIndex = seg.index + 1;
  }
  // The ordered log is every finalized segment (oldest first) followed by
  // the active log file.
  const ordered = segments.map((seg) => seg.path);
  if (existsSync(logPath)) ordered.push(logPath);

  // The newest anchor — a segment whose first line is a compact ('c') or
  // truncate ('t') marker for the current snapshot generation — starts the
  // live suffix of the log. Everything before it is folded into the snapshot
  // or checkpointed into that marker.
  let startAt = -1;
  for (let i = 0; i < ordered.length; i++) {
    const first = firstEntry(ordered[i]);
    if (first && (first.t === 'c' || first.t === 't') && first.gen === snapshotGen) {
      startAt = i;
    }
  }

  if (snapshotGen > 0 && startAt < 0) {
    // Crash between the snapshot rename and the log reset: every byte still
    // on disk is already folded into the snapshot. Reset to a marker-led log
    // so the state is unambiguous from here on.
    for (const seg of segments) rmSync(seg.path, { force: true });
    writeFileSync(logPath, markerLine(snapshotGen));
  } else {
    // Replay the live suffix; a torn tail or uncommitted batch is severed.
    for (let i = Math.max(startAt, 0); i < ordered.length; i++) {
      const raw = readFileSync(ordered[i]);
      const committedEnd = recoverLog(raw);
      if (committedEnd < raw.length) truncateSync(ordered[i], committedEnd);
    }
    // Reconcile leftovers of an interrupted truncate/compact: finalized
    // segments before the anchor whose content is folded into the snapshot
    // or at/below the truncation horizon can go. Segments a consumer still
    // needs (above the horizon) stay untouched.
    for (let i = 0; i < startAt; i++) {
      const max = segmentMaxSeq(ordered[i]);
      if (max === null || max <= foldedSeq || max <= horizon) {
        rmSync(ordered[i], { force: true });
      }
    }
  }

  // Recompute retained bytes from the surviving messages after recovery:
  // snapshot survivors plus messages in finalized segments and the active
  // log above both the horizon and the folded floor. Torn tails and
  // uncommitted batches were severed above, so their bytes never count —
  // usage always matches the messages actually alive.
  for (const m of baseMessages) {
    if (m.seq > horizon) usageBytes += Buffer.byteLength(JSON.stringify(m.record), 'utf8');
  }
  {
    const logFloor = Math.max(horizon, foldedSeq);
    const sumFile = (filePath) => {
      if (!existsSync(filePath)) return;
      const { entries } = parseLog(readFileSync(filePath));
      for (const entry of entries) {
        if (entry.t === 'm' && entry.seq > logFloor) usageBytes += entry.bytes;
      }
    };
    for (const seg of listSegments()) sumFile(seg.path);
    sumFile(logPath);
  }

  // Reassigned by compact()/truncate() when they swap the active log. This
  // instance opens the log with O_APPEND so its position writes (which do not
  // go through the write lock) coexist with a lease-holding writer appending
  // to the same file: each writev is a single O_APPEND line and the kernel
  // interleaves whole lines, never bytes within one.
  let fd = openSync(logPath, 'a');
  let logIno = statOrNull(logPath)?.ino ?? 0;
  let logSize = statOrNull(logPath)?.size ?? 0;
  let snapMtimeMs = statOrNull(snapshotPath)?.mtimeMs ?? 0;

  function statOrNull(p) {
    try {
      return statSync(p);
    } catch {
      return null;
    }
  }

  let chain = Promise.resolve();
  let closed = false;
  // A failed append may leave a torn line; stop appending so later writes
  // cannot glue themselves onto it. The torn tail is truncated on reopen
  // (and, across processes, on lease takeover).
  let broken = false;
  // Set while a takeover reload is rebuilding in-memory state from disk;
  // queued serial jobs wait for it before judging ownership again.
  let reloadInProgress = null;
  // A position/replay line this opener appended beyond `logSize`, used to
  // tell its own bytes apart from a foreign writer's when catching up.
  let ownTail = Buffer.alloc(0);

  // All disk mutation by publish/replay/compact/truncate happens inside this
  // serial chain; writeSync keeps each append atomic with respect to the
  // event loop while still returning a Promise to callers.
  const enqueue = (job) => {
    const run = chain.then(job);
    // A failed job must not stall every later operation.
    chain = run.then(
      () => {},
      () => {},
    );
    return run;
  };

  // ---- lease handling ------------------------------------------------------

  const readLease = () => {
    try {
      return JSON.parse(readFileSync(leasePath, 'utf8'));
    } catch {
      return null;
    }
  };

  // Atomically publish `lease` and read the winner back. tmp+rename+readback
  // is the arbitration: whoever's bytes are on disk after the rename owns it.
  const commitLease = (lease) => {
    const body = JSON.stringify(lease);
    const tmpFd = openSync(leaseTmpPath, 'w');
    try {
      writeSync(tmpFd, Buffer.from(body, 'utf8'));
      fsyncSync(tmpFd);
    } finally {
      closeSync(tmpFd);
    }
    renameSync(leaseTmpPath, leasePath);
    try {
      const dirFd = openSync(dir, 'r');
      try {
        fsyncSync(dirFd);
      } finally {
        closeSync(dirFd);
      }
    } catch {
      // Directory sync unavailable: the rename itself already landed; only
      // its crash durability is weakened.
    }
    return readLease();
  };

  const isCurrentLease = (lease) =>
    !!lease && lease.owner === ownerId && lease.epoch === leaseEpoch;

  // True when a foreign lease may be discarded: its deadline is in the past
  // even allowing for clock skew. A lease this instance owns is never "stale"
  // on its own clock — takeover across that boundary is driven by the epoch
  // fence another writer writes, not by self-expiry.
  const foreignLeaseStale = (lease, now) =>
    !lease || lease.owner !== ownerId
      ? !lease || now > lease.expiresAt + CLOCK_SKEW_MS
      : false;

  const stopHeartbeat = () => {
    if (heartbeat) {
      clearInterval(heartbeat);
      heartbeat = null;
    }
  };

  const startHeartbeat = () => {
    if (heartbeat || closed) return;
    heartbeat = setInterval(() => {
      if (closed) return;
      if (leaseBusy > 0) return; // a serial job is mid-flight; it renews itself
      const cur = readLease();
      // Fenced (another epoch/owner on disk): stop claiming.
      if (cur && cur.owner === ownerId && cur.epoch !== leaseEpoch) {
        stopHeartbeat();
        return;
      }
      if (!cur || cur.owner !== ownerId) {
        stopHeartbeat();
        return;
      }
      const now = Date.now();
      // Renew a little early; if still well inside the term there is nothing
      // to do this tick.
      if (now < leaseExpiresAt - (LEASE_MS - RENEW_AT_MS)) return;
      try {
        const winner = commitLease({ ...cur, expiresAt: now + LEASE_MS });
        if (isCurrentLease(winner)) {
          leaseExpiresAt = winner.expiresAt;
        } else {
          stopHeartbeat();
        }
      } catch {
        // A failed heartbeat (e.g. ENOSPC) means the term may simply run out;
        // the next write-path call re-checks and reacquires or refuses.
      }
    }, Math.min(500, RENEW_AT_MS / 2));
    // The interval must not keep the event loop alive on its own.
    if (typeof heartbeat.unref === 'function') heartbeat.unref();
  };

  const sleep = (ms) => new Promise((resolve) => setTimeout(resolve, ms));

  // Become the writer. Resolves when this instance holds a current lease
  // (after taking over, once the predecessor's torn tail is severed and its
  // state is merged); rejects with an Error if ownership cannot be obtained
  // because a live owner keeps it, the directory is gone, or access is
  // denied. Disk-full surfaces as the underlying Error (never RangeError —
  // quota failures originate in the call sites instead).
  const acquire = async () => {
    if (closed || broken) throw new Error('bus is closed');
    for (;;) {
      if (closed) throw new Error('bus is closed');
      const now = Date.now();
      const cur = readLease();
      if (cur && cur.owner === ownerId && cur.epoch === leaseEpoch && now <= leaseExpiresAt) {
        startHeartbeat();
        return;
      }
      if (cur && !foreignLeaseStale(cur, now)) {
        // Someone else holds a valid lease. Wait out the remainder of its
        // term (plus skew grace) and retry — bounded, never a busy spin.
        const wait = Math.max(RETRY_MS, cur.expiresAt + CLOCK_SKEW_MS - now + 25);
        await sleep(Math.min(wait, LEASE_MS + CLOCK_SKEW_MS + 50));
        continue;
      }
      const epoch = (cur && typeof cur.epoch === 'number' ? cur.epoch : 0) + 1;
      const lease = { owner: ownerId, epoch, acquiredAt: now, expiresAt: now + LEASE_MS };
      let winner;
      try {
        winner = commitLease(lease);
      } catch (err) {
        // No permission, directory removed, disk full: the write path
        // refuses with an Error and state stays untouched.
        throw err instanceof Error ? err : new Error(String(err));
      }
      if (isCurrentLeaseWinner(winner, ownerId, epoch)) {
        leaseEpoch = epoch;
        leaseExpiresAt = lease.expiresAt;
        // We just fenced the previous owner (or the file was free). Its last
        // append may be torn and its in-memory state is not ours: rebuild
        // from disk before writing a single byte.
        try {
          await takeoverReload();
        } catch (err) {
          broken = true;
          stopHeartbeat();
          throw err instanceof Error ? err : new Error(String(err));
        }
        startHeartbeat();
        return;
      }
      // Lost a rename race to a live contender; loop and re-read.
    }
  };

  const isCurrentLeaseWinner = (lease, owner, epoch) =>
    !!lease && lease.owner === owner && lease.epoch === epoch;

  // Refresh the term while holding the lock; if the lease was stolen, fail
  // the caller (the serial job) with an ownership Error before any write.
  const ensureLease = () => {
    if (closed || broken) throw new Error('bus is closed');
    const cur = readLease();
    if (!cur || cur.owner !== ownerId || cur.epoch !== leaseEpoch) {
      stopHeartbeat();
      throw new Error('bus write ownership was taken by another process');
    }
    const now = Date.now();
    if (now >= leaseExpiresAt - (LEASE_MS - RENEW_AT_MS)) {
      const winner = commitLease({ ...cur, expiresAt: now + LEASE_MS });
      if (!isCurrentLease(winner)) {
        stopHeartbeat();
        throw new Error('bus write ownership was taken by another process');
      }
      leaseExpiresAt = winner.expiresAt;
    }
  };

  // Drop the lease cleanly when a writer goes idle / closes, so contenders
  // take over immediately instead of waiting for the term to run out.
  const releaseLease = () => {
    stopHeartbeat();
    if (leaseEpoch === 0) return;
    const epoch = leaseEpoch;
    leaseExpiresAt = 0;
    leaseEpoch = 0;
    try {
      const cur = readLease();
      if (cur && cur.owner === ownerId && cur.epoch === epoch) {
        rmSync(leasePath, { force: true });
      }
    } catch {
      // Best effort: if the release unlink fails the term simply expires.
    }
  };

  // ---- state merging across writers ----------------------------------------

  // Recompute every merged value from the directory: snapshot plus the live
  // suffix of the log, severing a torn tail / dangling batch the previous
  // owner may have left. Used at open time recovery boundaries, takeover and
  // whenever the active log file or snapshot is observed to have changed.
  const loadStateFromDisk = ({ sever = true } = {}) => {
    const sSeq = seq;
    void sSeq;
    let nSeq = 0;
    let nBytes = 0;
    let nPublished = 0;
    let nReplayed = 0;
    let nHorizon = 0;
    let nFoldedSeq = 0;
    let nGen = 0;
    let nBase = [];
    const nDedup = new Map();
    const nPositions = new Map();
    let nUsage = 0;
    let nNextSegment = 1;

    if (existsSync(snapshotPath)) {
      const snap = JSON.parse(readFileSync(snapshotPath, 'utf8'));
      nGen = snap.gen;
      nSeq = snap.seq;
      nBytes = snap.bytes;
      nPublished = snap.published;
      nReplayed = snap.replayed;
      nHorizon = snap.horizon ?? 0;
      nFoldedSeq = snap.seq;
      for (const [key, value] of snap.dedup) nDedup.set(key, value);
      for (const [name, pos] of Object.entries(snap.positions)) nPositions.set(name, pos);
      nBase = snap.messages;
    }

    const segs = listSegments();
    for (const seg of segs) {
      if (seg.index >= nNextSegment) nNextSegment = seg.index + 1;
    }
    const files = segs.map((seg) => seg.path);
    if (existsSync(logPath)) files.push(logPath);

    let anchor = -1;
    for (let i = 0; i < files.length; i++) {
      const first = firstEntry(files[i]);
      if (first && (first.t === 'c' || first.t === 't') && first.gen === nGen) {
        anchor = i;
      }
    }

    if (nGen > 0 && anchor < 0) {
      // Snapshot landed without its marker-led log (a compact crashed in that
      // window, or another process is mid-swap). Nothing on disk can extend
      // the snapshot; regenerate the marker log so subsequent appends anchor.
      for (const seg of segs) rmSync(seg.path, { force: true });
      writeFileSync(logPath, markerLine(nGen));
      files.length = 0;
      files.push(logPath);
      anchor = 0;
    }

    const start = Math.max(anchor, 0);
    for (let i = start; i < files.length; i++) {
      const filePath = files[i];
      const raw = readFileSync(filePath);
      let committed;
      let committedEnd = raw.length;
      if (sever) {
        // Strict recovery so a torn tail is both ignored and, for the active
        // log, physically severed — exactly like open-time recovery.
        committedEnd = recoverInto(raw, {
          onEntry: (e) => applyLoadEntry(e, nState()),
          onMarker: (e) => applyLoadMarker(e, nState()),
        });
        if (committedEnd < raw.length && filePath === logPath) {
          truncateSync(logPath, committedEnd);
        }
        committed = null;
      } else {
        committed = parseCommitted(raw, { strict: false });
        for (const e of committed) {
          if (e.t === 't') applyLoadMarker(e, nState());
          else applyLoadEntry(e, nState());
        }
      }
      void committed;
    }

    function nState() {
      return {
        seq: nSeq,
        set seq(v) {
          nSeq = v;
        },
        bytes: 0,
      };
    }

    // The above closures need mutable access; implement the appliers against
    // a shared state bag instead (kept outside to avoid the awkward stub).
    const bag = {
      seq: nSeq,
      bytes: nBytes,
      published: nPublished,
      replayed: nReplayed,
      horizon: nHorizon,
      positions: nPositions,
      dedup: nDedup,
    };
    void bag;

    for (const m of nBase) {
      if (m.seq > nHorizon) nUsage += Buffer.byteLength(JSON.stringify(m.record), 'utf8');
    }
    const logFloor = Math.max(nHorizon, nFoldedSeq);
    const sumFile = (filePath) => {
      if (!existsSync(filePath)) return;
      const { entries } = parseLog(readFileSync(filePath));
      for (const entry of entries) {
        if (entry.t === 'm' && entry.seq > logFloor) nUsage += entry.bytes;
      }
    };
    for (const seg of listSegments()) sumFile(seg.path);
    sumFile(logPath);

    return {
      seq: bagFinal.seq,
      bytes: bagFinal.bytes,
      published: bagFinal.published,
      replayed: bagFinal.replayed,
      horizon: bagFinal.horizon,
      foldedSeq: nFoldedSeq,
      gen: nGen,
      base: nBase,
      dedup: nDedup,
      positions: nPositions,
      usage: nUsage,
      nextSegmentIndex: nNextSegment,
    };

    function bagFinal() {}
  };

  // The dynamic-state appliers used by full reloads. Kept tiny on purpose.
  const applyLoadEntry = (entry, st) => {
    if (entry.t === 'm') {
      if (entry.seq <= st.horizon) return;
      st.seq = entry.seq;
      st.bytes += entry.bytes;
      st.published += 1;
      if (typeof entry.d === 'string') st.dedup.set(entry.d, { id: entry.id, seq: entry.seq });
    } else if (entry.t === 's') {
      st.replayed += entry.n;
    } else if (entry.t === 'p') {
      st.positions.set(entry.name, entry.pos);
    }
  };
  const applyLoadMarker = (entry, st) => {
    st.seq = entry.seq;
    st.bytes = entry.bytes;
    st.published = entry.published;
    st.replayed = entry.replayed;
    st.horizon = entry.horizon;
    st.positions.clear();
    for (const [name, pos] of Object.entries(entry.positions)) st.positions.set(name, pos);
    st.dedup.clear();
    for (const [key, value] of entry.dedup) st.dedup.set(key, value);
  };

  // Walk a raw log applying only the committed prefix, the same rules as
