// Parse the complete lines of an append-only meta sidecar buffer. A torn
// final line (another process crashed mid-write) is simply absent.
function parseMeta(raw) {
  const entries = [];
  let start = 0;
  for (let i = 0; i < raw.length; i++) {
    if (raw[i] !== 0x0a) continue;
    if (i > start) {
      try {
        entries.push(JSON.parse(raw.toString('utf8', start, i)));
      } catch {
        // Torn/garbled line: stop here; nothing after it is trustworthy.
        break;
      }
    }
    start = i + 1;
  }
  return entries;
}

