// final line (another process crashed mid-write) is skipped, not fatal;
// writers heal such a tail by emitting a newline before their next line, so
// every complete line before and after it stays readable.
function parseMeta(raw) {
  const entries = [];
  let start = 0;
  for (let i = 0; i < raw.length; i++) {
    if (raw[i] !== 0x0a) continue;
    if (i > start) {
      try {
        entries.push(JSON.parse(raw.toString('utf8', start, i)));
      } catch {
        // Torn/garbled line: isolated by its newline(s); skip it alone.
      }
    }
    start = i + 1;
  }
  return entries;
}

