// Append one shared-state line. Goes to the stable sidecar via a single
// O_APPEND writev, so concurrent processes interleave whole lines. A
// damaged handle is reopened once before giving up.
const writeMetaLine = (entry) => {
  const buf = Buffer.from(JSON.stringify(entry) + '\n', 'utf8');
  try {
    writeSync(metaFd, buf);
    if (fsync) fsyncSync(metaFd);
  } catch (err) {
    try {
      closeSync(metaFd);
    } catch {
      // ignore
    }
    metaFd = openSync(metaPath, 'a');
    writeSync(metaFd, buf);
    if (fsync) fsyncSync(metaFd);
    void err;
  }
  metaSize = statOrNull(metaPath)?.size ?? metaSize;
};

