const stopHeartbeat = () => {
  if (heartbeat) {
    clearInterval(heartbeat);
    heartbeat = null;
  }
};

const startHeartbeat = () => {
  if (heartbeat || closed) return;
  heartbeat = setInterval(() => {
    if (closed) return;
    const cur = readLease();
    if (!cur || cur.owner !== ownerId || cur.epoch !== leaseEpoch) {
      // Fenced or released: nothing of ours to keep alive.
      stopHeartbeat();
      return;
    }
    const now = Date.now();
    if (now < leaseExpiresAt - (LEASE_MS - RENEW_AT_MS)) return;
    try {
      const winner = commitLease({
        owner: ownerId,
        epoch: leaseEpoch,
        acquiredAt: cur.acquiredAt ?? now,
        expiresAt: now + LEASE_MS,
      });
      if (winner && winner.owner === ownerId && winner.epoch === leaseEpoch) {
        leaseExpiresAt = winner.expiresAt;
      } else {
        stopHeartbeat();
      }
    } catch {
      // A failed heartbeat (e.g. ENOSPC) simply lets the term run out; the
      // next mutating call re-validates and reacquires or refuses.
    }
  }, Math.min(500, RENEW_AT_MS / 2));
  // Never keep the event loop alive just for the heartbeat.
  if (typeof heartbeat.unref === 'function') heartbeat.unref();
};

const sleep = (ms) => new Promise((resolve) => setTimeout(resolve, ms));

// Rebuild all merged state from disk. With `sever` true (only the lease
// owner runs this) a predecessor's torn tail / dangling batch is physically
// truncated exactly like open-time recovery; with `sever` false (a read-
// only opener catching up) nothing on disk is modified.
const rebuildState = ({ sever } = {}) => {
  const bag = {
    seq: 0,
    bytes: 0,
    published: 0,
    replayed: 0,
    horizon: 0,
    positions: new Map(),
    dedup: new Map(),
  };

