// Release the current term once the serial chain has drained, so a
// contender takes over immediately. Enqueued like any job: if a new
// mutating call is already queued ahead of it, that call keeps the term
// and this job stands down (leaseBusy > 0). The epoch directory stays as
// the arbitration record, marked with a release flag.
const scheduleIdleRelease = () => {
  enqueue(() => {
    if (leaseBusy > 0 || closed) return;
    stopHeartbeat();
    if (leaseEpoch === 0) return;
    markReleased();
    leaseEpoch = 0;
    leaseExpiresAt = 0;
  });
};

// Wrap a mutating chain job: count it as lease activity while it runs and
// arm the idle release once the chain drains.
const trackLeaseJob = (job) => () =>
  Promise.resolve()
    .then(job)
    .then(
      (v) => {
        leaseBusy -= 1;
        if (leaseBusy === 0) scheduleIdleRelease();
        return v;
      },
      (err) => {
        leaseBusy -= 1;
        if (leaseBusy === 0) scheduleIdleRelease();
        throw err;
      },
    );

