test('multi-process: an unwritable directory rejects writes with Error', { skip: process.getuid?.() === 0 }, async () => {
  const dir = await freshDir();
  const a = new Worker('A');
  await a.open(dir);
  await a.publish({ i: 1 });
  await a.sleep(20); // release the lease first

  await chmod(dir, 0o755).catch(() => {});
  // Make the directory tree read-only recursively: existing files stay
  // readable (and already-open handles stay usable) but creating any new
  // lease/snapshot/log entry fails.
  execSync(`chmod -R a=rX "${dir}"`);
  try {
    await assert.rejects(a.publish({ i: 2 }), (e) => e.name === 'Error');
    // Read paths still return data.
    assert.deepEqual((await a.read('r')).map((m) => m.seq), [1]);
  } finally {
    execSync(`chmod -R u+w "${dir}"`);
  }
  await a.end();
});

